// Intended function: match remote surplus to deficits in bounded stable-ID order, leaving local hauling and ship materialization to active-site owners.
#include "world/OutpostNetwork.hpp"
#include "core/Determinism.hpp"
#include <algorithm>
namespace elysium{bool OutpostNetwork::upsert(OutpostRecord o){if(!o.outpostId)return false;outposts_[o.outpostId]=std::move(o);return true;}std::optional<OutpostRecord>OutpostNetwork::find(std::uint64_t id)const{auto i=outposts_.find(id);return i==outposts_.end()?std::nullopt:std::optional<OutpostRecord>(i->second);}std::vector<OutpostTransfer>OutpostNetwork::planDeficitTransfers(std::uint64_t tick,std::uint32_t max,std::uint64_t travel){std::vector<std::uint64_t>ids;for(auto&[id,_]:outposts_)ids.push_back(id);std::sort(ids.begin(),ids.end());std::vector<OutpostTransfer>o;for(auto dst:ids){auto&d=outposts_[dst];for(auto&need:d.stocks){if(need.quantity>=need.desiredReserve)continue;auto deficit=need.desiredReserve-need.quantity;for(auto src:ids){if(src==dst)continue;auto&s=outposts_[src];auto it=std::find_if(s.stocks.begin(),s.stocks.end(),[&](auto&x){return x.itemId==need.itemId&&x.quantity>x.desiredReserve;});if(it==s.stocks.end())continue;auto q=std::min(deficit,it->quantity-it->desiredReserve);if(!q)continue;it->quantity-=q;deficit-=q;auto tid=mix64((nextTransfer_++)^src^mix64(dst)^need.itemId);o.push_back({tid,src,dst,need.itemId,q,tick,tick+travel});if(o.size()>=max||!deficit)return o;}}}return o;}void OutpostNetwork::applyArrival(const OutpostTransfer&t){auto i=outposts_.find(t.toOutpost);if(i==outposts_.end())return;auto&v=i->second.stocks;auto s=std::find_if(v.begin(),v.end(),[&](auto&x){return x.itemId==t.itemId;});if(s==v.end())v.push_back({t.itemId,t.quantity,0});else s->quantity+=t.quantity;}}
